#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate opt-in Sarasa A4 fonts for round navigation and battle text."""
import struct

from PIL import Image, ImageDraw, ImageFont

from generate_font16cn import (ROOT, SARASA_FONT_PATH, PACK_FONT_REGULAR_OUT, UNSCII_CHARS,
                              collect_ui_chars, collect_pack_text_chars)

# Expand this subset when another label adopts smooth text. Existing game
# fonts and pixel art are deliberately generated by their original pipeline.
LABELS = "市集菜单商店购买出售背包电脑队伍房间伙伴设置操作说明重置游戏状态初始蛋技能探索青草径溪桥坡高草园霜晶窟雾林径古瀑谷结束返回"
BATTLE_COMMANDS = "战斗背包替换逃跑"
HEADER = struct.Struct("<IHHBBBBI")


def glyph_alpha(font, char, size):
    image = Image.new("L", (size, size), 0)
    # Baseline matches the original font cells, with no bitmap resampling.
    ImageDraw.Draw(image).text((0, size - 1), char, font=font,
                               fill=255, anchor="ls")
    values = [(value * 15 + 127) // 255 for value in image.tobytes()]
    return bytes((values[i] << 4) | values[i + 1]
                 for i in range(0, len(values), 2))


def generate(output=None):
    output = output or ROOT / "data/packs/dev/fonts"
    output.mkdir(parents=True, exist_ok=True)
    for size in (16, 20):
        chars = set(LABELS + BATTLE_COMMANDS)
        if size == 16:
            # Dynamic species, moves and battle logs share the regular font's
            # character sources. Keep ASCII and gender signs in Unscii.
            chars.update(collect_ui_chars())
            chars.update(collect_pack_text_chars())
            # Include every character available to the running game, including
            # retained pack glyphs that are absent from today's source text.
            regular = PACK_FONT_REGULAR_OUT.read_bytes()
            magic, version, count, width, height, stride, reserved, flags = HEADER.unpack_from(regular)
            if (magic, version, width, height, stride, reserved, flags) != (0x4E464D53, 1, 16, 16, 32, 0, 0):
                raise ValueError("Unexpected regular font format")
            if len(regular) != HEADER.size + count * (4 + stride):
                raise ValueError("Truncated regular font")
            chars.update(chr(struct.unpack_from("<I", regular, HEADER.size + i * (4 + stride))[0])
                         for i in range(count))
            chars.difference_update(UNSCII_CHARS)
        chars = sorted(chars, key=ord)
        font = ImageFont.truetype(str(SARASA_FONT_PATH), size)
        payload = b"".join(struct.pack("<I", ord(char)) +
                           glyph_alpha(font, char, size) for char in chars)
        # SMFN v2: A4 coverage, high nibble first; no row padding.
        header = HEADER.pack(0x4E464D53, 2, len(chars), size, size,
                             size * size // 2, 0, 4)
        path = output / f"round-zh{size}-a4.smonfont"
        path.write_bytes(header + payload)
        print(f"Sarasa {size}px A4: {len(chars)} glyphs, {path.stat().st_size} bytes -> {path}")


if __name__ == "__main__":
    generate()
